        }


@dataclass
class TimelineSchedule:
    """The master timeline schedule defining all visual segments across the full audio."""
    story_dir: Path
    audio_path: Path
    total_duration: float
    segments: List[VisualSegment] = field(default_factory=list)
    format_id: str = "F2"
    creative_plan_fingerprint: str = ""
    format_plan_fingerprint: str = ""
    editorial_timeline_fingerprint: str = ""
    compose_plan_fingerprint: str = ""
    effect_profile_fingerprint: str = ""
    editorial_qc_verdict: str = "PASS"
    owner_disposition: str = "AUTO"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "story_dir": str(self.story_dir),
            "audio_path": str(self.audio_path),
            "total_duration": round(self.total_duration, 2),
            "segment_count": len(self.segments),
            "format_id": self.format_id,
            "creative_plan_fingerprint": self.creative_plan_fingerprint,
            "format_plan_fingerprint": self.format_plan_fingerprint,
            "editorial_timeline_fingerprint": self.editorial_timeline_fingerprint,
            "compose_plan_fingerprint": self.compose_plan_fingerprint,
            "effect_profile_fingerprint": self.effect_profile_fingerprint,
            "editorial_qc_verdict": self.editorial_qc_verdict,
            "owner_disposition": self.owner_disposition,
            "segments": [s.to_dict() for s in self.segments]
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TimelineSchedule":
        segments = [
            VisualSegment(
                index=s["index"],
                start_time=s["start"],
                duration=s["duration"],
                segment_type=s["type"],
                source_path=Path(s["source"]),
                description=s.get("description", ""),
                is_loop=s.get("is_loop", False),
                speed_factor=s.get("speed_factor", 1.0),
                source_class=SourceClass(s["source_class"]) if s.get("source_class") else None,
                asset_id=s.get("asset_id", ""),
                in_point=s.get("in_point", 0.0),
                out_point=s.get("out_point", 0.0)
            )
            for s in data.get("segments", [])
        ]
        return cls(
            story_dir=Path(data["story_dir"]),
            audio_path=Path(data["audio_path"]),
            total_duration=data["total_duration"],
            segments=segments,
            format_id=data.get("format_id", "F2"),
            creative_plan_fingerprint=data.get("creative_plan_fingerprint", ""),
            format_plan_fingerprint=data.get("format_plan_fingerprint", ""),
            editorial_timeline_fingerprint=data.get("editorial_timeline_fingerprint", ""),
            compose_plan_fingerprint=data.get("compose_plan_fingerprint", ""),
            effect_profile_fingerprint=data.get("effect_profile_fingerprint", ""),
            editorial_qc_verdict=data.get("editorial_qc_verdict", "PASS"),
            owner_disposition=data.get("owner_disposition", "AUTO")
        )


