@dataclass
class CreativePlan:
    """Creative specification compiled from script understanding."""
    creative_plan_id: str
    story_title: str
    format_plan: FormatPlan
    scenes: List[Scene] = field(default_factory=list)
    beats: List[Beat] = field(default_factory=list)
    characters: List[Character] = field(default_factory=list)
    locations: List[Location] = field(default_factory=list)
    props: List[Prop] = field(default_factory=list)
    world_state: WorldState = field(default_factory=WorldState)
    shot_specs: List[ShotSpec] = field(default_factory=list)
    fingerprint: str = ""

    def compute_fingerprint(self) -> str:
        """Deterministic canonical fingerprint over all acceptance-relevant semantic content."""
        payload = {
            "creative_plan_id": self.creative_plan_id,
            "story_title": self.story_title,
            "format_plan_fingerprint": self.format_plan.fingerprint if self.format_plan else "",
            "scenes": [
                {
                    "scene_id": s.scene_id,
                    "scene_index": getattr(s, "scene_index", 0),
                    "start_sec": getattr(s, "start_sec", 0.0),
                    "end_sec": getattr(s, "end_sec", 0.0),
                    "location_id": getattr(s, "location_id", ""),
                    "time_context": getattr(s, "time_context", ""),
                    "story_state": getattr(s, "story_state", ""),
                    "active_characters": sorted(getattr(s, "active_characters", []) or []),
                    "dramatic_goal": getattr(s, "dramatic_goal", "")
                }
                for s in sorted(self.scenes, key=lambda x: x.scene_id)
            ],
            "beats": [
                {
                    "beat_id": b.beat_id,
                    "start_sec": getattr(b.narration_span, "start_sec", 0.0) if getattr(b, "narration_span", None) else 0.0,
                    "end_sec": getattr(b.narration_span, "end_sec", 0.0) if getattr(b, "narration_span", None) else 0.0,
                    "dramatic_function": getattr(b, "dramatic_function", ""),
                    "active_characters": sorted(getattr(b, "active_characters", []) or []),
                    "emotional_tone": getattr(b, "emotional_tone", "neutral"),
                    "is_major": getattr(b, "is_major", True)
                }
                for b in sorted(
                    self.beats,
                    key=lambda x: (getattr(x.narration_span, "start_sec", 0.0) if getattr(x, "narration_span", None) else 0.0, x.beat_id)
                )
            ],
            "characters": [
                {
                    "character_id": c.character_id,
                    "name": c.name,
                    "reference_version": getattr(c, "reference_version", "v1.0"),
                    "visual_dna": getattr(c, "canonical_dna", "")
                }
                for c in sorted(self.characters, key=lambda x: x.character_id)
            ],
            "locations": [
                {
                    "location_id": loc.location_id,
                    "name": loc.name,
                    "location_dna": getattr(loc, "location_dna", ""),
                    "environment_type": getattr(loc, "environment_type", "interior")
                }
                for loc in sorted(self.locations, key=lambda x: x.location_id)
            ],
            "props": [
                {
                    "prop_id": p.prop_id,
                    "name": p.name,
                    "owner": p.current_owner_character_id,
                    "location": p.current_location_id,
                    "state": p.state
                }
                for p in sorted(self.props, key=lambda x: x.prop_id)
            ],
            "world_state": {
                "character_states": getattr(self.world_state, "character_states", {}),
                "prop_states": getattr(self.world_state, "prop_states", {}),
                "location_states": getattr(self.world_state, "location_states", {}),
                "narrative_knowledge": getattr(self.world_state, "narrative_knowledge", {})
            } if self.world_state else {},
            "shot_specs": [
                {
                    "shot_id": sh.shot_id,
                    "scene_id": sh.scene_id,
                    "duration_sec": sh.duration_sec,
                    "shot_type": sh.shot_type,
                    "camera_motion": sh.camera_motion,
                    "primary_subject": sh.primary_subject,
                    "primary_action": sh.primary_action,
                    "entry_state": sh.entry_state,
                    "action_or_event": sh.action_or_event,
                    "exit_state": sh.exit_state,
                    "continuity_from": sh.continuity_from,
                    "continuity_to": sh.continuity_to,
                    "visual_requirement": {
                        "preferred_source_class": sh.visual_requirement.preferred_source_class.value if sh.visual_requirement and hasattr(sh.visual_requirement.preferred_source_class, "value") else (str(sh.visual_requirement.preferred_source_class) if sh.visual_requirement else ""),
                        "stock_search_intent": sh.visual_requirement.stock_search_intent if sh.visual_requirement else "",
                        "required_visuals": sorted(sh.visual_requirement.required_visuals) if sh.visual_requirement else [],
                        "forbidden_visuals": sorted(sh.visual_requirement.forbidden_visuals) if sh.visual_requirement else []
                    } if sh.visual_requirement else {}
                }
                for sh in self.shot_specs
            ]
        }
        canonical_str = json.dumps(payload, sort_keys=True, ensure_ascii=True)
        return hashlib.sha256(canonical_str.encode("utf-8")).hexdigest()[:16]

    def __post_init__(self):
        if not self.fingerprint:
            self.fingerprint = self.compute_fingerprint()


