    audios = list(story_dir.glob("*.m4a")) + list(story_dir.glob("*.mp3")) + list(story_dir.glob("*.wav"))
    srts = list(story_dir.glob("*.srt"))
    
    if not audios or not srts:
        return web.json_response({"status": "error", "message": "Missing audio or SRT in directory"}, status=400)

