    reg_stats = get_registry_stats()

    # Master Video
    master_path = story_dir / "Final_Video_Export" / "Full_Master_Video_26M.mp4"
    has_master = master_path.exists()
    master_info = {}
    if has_master:
        master_info = {
            "size_bytes": master_path.stat().st_size,
            "path": str(master_path.resolve()),
            "name": master_path.name
