    if previews_dir.exists():
        for img in sorted(previews_dir.glob("*.jpg")):
            previews.append({
                "name": img.name,
                "path": str(img.resolve()),
                "size": img.stat().st_size
            })

    # Schedule if exists
    sched_file = story_dir / "fast_pipeline" / "video_schedule.json"
    schedule_data = {}
    if sched_file.exists():
        try:
            with open(sched_file, "r", encoding="utf-8") as f:
                schedule_data = json.load(f)
        except Exception:
            pass

    audio_list = []
    for a in audios:
        try:
            sz = a.stat().st_size
        except Exception:
            sz = 0
        audio_list.append({"name": a.name, "path": str(a.resolve()), "size": sz})

    srt_list = []
    for s in srts:
        try:
            sz = s.stat().st_size
        except Exception:
            sz = 0
        srt_list.append({"name": s.name, "path": str(s.resolve()), "size": sz})

    return web.json_response({
        "status": "ok",
        "story_name": story_dir.name,
        "story_path": str(story_dir.resolve()),
        "audio": {
            "name": chosen_audio.name,
            "path": str(chosen_audio.resolve()),
            "duration": total_dur
        },
        "audio_files": audio_list,
        "subtitles": {
            "name": chosen_srt.name,
            "cue_count": len(cues),
            "sample_cues": [
                {"index": c.index, "start": c.start_sec, "end": c.end_sec, "text": c.text}
                for c in cues[:10]
            ]
        },
        "srt_files": srt_list,
        "plan": plan,
        "assets": {
            "stock_count": stock_mgr.unused_count,
            "stock_total": stock_mgr.total_count,
            "stock_files": [{"name": p.name, "path": str(p.resolve())} for p in stock_mgr.get_unused_pool()[:12]],
            "veo_count": len(veo_clips),
            "veo_files": [{"name": p.name, "path": str(p.resolve())} for p in veo_clips],
            "cookie_valid": val_cookie.get("valid", False),
            "registry": reg_stats
        },
        "master_video": master_info,
        "qa_previews": previews,
        "schedule": schedule_data
    })

async def handle_stream_media(request):
    """
    HTTP Range Request media streamer.
    Allows seeking and smooth playback of large video files in HTML5 video players.
    """
    path_str = request.query.get("path", "")
    if not path_str:
        return web.Response(text="Missing path", status=400)

    file_path = Path(path_str)
    if not file_path.exists() or not file_path.is_file():
        return web.Response(text="File not found", status=404)

    file_size = file_path.stat().st_size
    range_header = request.headers.get("Range")

    content_type = "video/mp4"
    if file_path.suffix.lower() in (".jpg", ".jpeg"):
        content_type = "image/jpeg"
    elif file_path.suffix.lower() == ".png":
        content_type = "image/png"
    elif file_path.suffix.lower() in (".m4a", ".mp3", ".wav"):
        content_type = "audio/mp4"

    if not range_header:
        # Stream full content
        return web.FileResponse(file_path, headers={"Content-Type": content_type})

    # Range: bytes=START-END
    try:
        range_val = range_header.replace("bytes=", "").strip()
        start_str, end_str = range_val.split("-")
        start = int(start_str) if start_str else 0
        end = int(end_str) if end_str else file_size - 1
        if end >= file_size:
            end = file_size - 1
        length = end - start + 1
    except Exception:
        return web.Response(status=416)

    response = web.StreamResponse(
        status=206,
        reason="Partial Content",
        headers={
            "Content-Type": content_type,
            "Content-Range": f"bytes {start}-{end}/{file_size}",
            "Content-Length": str(length),
            "Accept-Ranges": "bytes",
        }
    )
    await response.prepare(request)

    with open(file_path, "rb") as f:
        f.seek(start)
        remaining = length
        chunk_size = 64 * 1024
        while remaining > 0:
            chunk = f.read(min(remaining, chunk_size))
            if not chunk:
                break
            await response.write(chunk)
            remaining -= len(chunk)

    await response.write_eof()
    return response

