def pick_file_native(title: str = "Chá»n video clip tÃ¹y chá»‰nh (.mp4, .mov, .mkv)", initialdir: str = str(BASE_DIR)) -> Optional[str]:
    """Spawns an isolated Python process to open a native OS file dialog on its main thread."""
    script = f"""
import tkinter as tk
from tkinter import filedialog
root = tk.Tk()
