    initialdir={repr(initialdir)},
    filetypes=[
        ("Video Files", "*.mp4 *.mov *.mkv *.webm"),
        ("All Files", "*.*")
    ]
)
root.destroy()
if f:
    print(f)
"""
    try:
        proc = subprocess.run(
