async def handle_get_editorial_qc_report(request):
    """Returns the latest EditorialQC analysis report for a story."""
    try:
        story_dir_str = request.query.get("story_dir", "")
        if not story_dir_str:
            return web.json_response({"status": "error", "message": "Thiáº¿u story_dir"}, status=400)
        story_dir = Path(story_dir_str)
        qc_file = story_dir / "fast_pipeline" / "editorial_qc_report.json"
        if qc_file.exists():
            data = json.loads(qc_file.read_text(encoding="utf-8"))
            return web.json_response({"status": "ok", "qc_report": data})
        if PIPELINE_STATE.get("editorial_qc"):
            return web.json_response({"status": "ok", "qc_report": PIPELINE_STATE["editorial_qc"]})
        return web.json_response({"status": "ok", "qc_report": None, "message": "ChÆ°a cÃ³ bÃ¡o cÃ¡o EditorialQC"})
    except Exception as e:
        return web.json_response({"status": "error", "message": str(e)}, status=500)

async def handle_editorial_qc_adjudicate(request):
    """Owner adjudication endpoint for EditorialQC (ACCEPT_OVERRIDE or REPLAN)."""
    try:
        data = await request.json()
        story_dir_str = data.get("story_dir", "")
        action = data.get("action", "ACCEPT_OVERRIDE")
        fmt = data.get("format", "f2")
        opts = data.get("options", {})
        if not story_dir_str:
            return web.json_response({"status": "error", "message": "Thiáº¿u story_dir"}, status=400)
        story_dir = Path(story_dir_str)
