            return web.json_response({"status": "error", "message": "ThÆ° má»¥c khÃ´ng tá»“n táº¡i"}, status=404)

        if action == "ACCEPT_OVERRIDE":
            opts["owner_override"] = True
            log_event(f"ðŸ›¡ï¸ [Owner Adjudication] Owner phÃª duyá»‡t ghi Ä‘Ã¨ (ACCEPT_OVERRIDE) cho {story_dir.name}.")
            asyncio.create_task(orchestrate_pipeline(story_dir, fmt, opts, dry_run=False))
